package com.scrollbehavior;

import net.runelite.client.config.*;

@ConfigGroup("scrollbehavior")
public interface ScrollBehaviorConfig extends Config
{
	@Range(
		min = 1,
		max = 300
	)
	@Units(
		value = Units.PERCENT
	)
	@ConfigItem(
		keyName = "scrollSensitivity",
		name = "Sensitivity",
		description = "Mouse wheel sensitivity as a percentage (100 is normal)",
		position = 1
	)
	default int scrollSensitivity()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "reverseScrollingDirection",
		name = "Reverse Scrolling Direction",
		description = "Reverse the direction in which you scroll",
		position = 2
	)
	default boolean reverseScrollingDirection()
	{
		return false;
	}
}

