package com.scrollbehavior;

import java.awt.Component;
import java.awt.event.MouseWheelEvent;
import javax.inject.Inject;
import net.runelite.client.input.MouseWheelListener;

public class ScrollBehaviorMouseWheelListener implements MouseWheelListener
{
	private static final double NORMAL_SENSITIVITY = 100;
	private static final double MIN_SENSITIVITY = 1;
	private static final double MAX_SENSITIVITY = 300;

	private final ScrollBehaviorConfig config;
	private double accumulatedRotation;
	private double previousSensitivity = NORMAL_SENSITIVITY;

	@Inject
	public ScrollBehaviorMouseWheelListener(ScrollBehaviorConfig config)
	{
		this.config = config;
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent event)
	{
		double sensitivity = Math.max(MIN_SENSITIVITY,
			Math.min(MAX_SENSITIVITY, config.scrollSensitivity()));

		boolean reverseScrollingDirection = config.reverseScrollingDirection();
		if (sensitivity == NORMAL_SENSITIVITY && !reverseScrollingDirection)
		{
			reset();
			return event;
		}

		if (sensitivity != previousSensitivity)
		{
			accumulatedRotation = 0;
			previousSensitivity = sensitivity;
		}

		double scaledRotation = event.getPreciseWheelRotation() * sensitivity / NORMAL_SENSITIVITY;
		if (reverseScrollingDirection)
		{
			scaledRotation *= -1;
		}

		if (accumulatedRotation != 0 && Math.signum(accumulatedRotation) != Math.signum(scaledRotation))
		{
			accumulatedRotation = 0;
		}

		accumulatedRotation += scaledRotation;
		int wheelRotation = (int) accumulatedRotation;
		accumulatedRotation -= wheelRotation;

		return new MouseWheelEvent(
			(Component) event.getSource(),
			event.getID(),
			event.getWhen(),
			event.getModifiersEx(),
			event.getX(),
			event.getY(),
			event.getClickCount(),
			event.isPopupTrigger(),
			event.getScrollType(),
			event.getScrollAmount(),
			wheelRotation);
	}

	void reset()
	{
		accumulatedRotation = 0;
		previousSensitivity = NORMAL_SENSITIVITY;
	}
}

package com.scrollbehavior;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Scroll Behavior"
)
public class ScrollBehaviorPlugin extends Plugin
{
	@Inject
	private MouseManager mouseManager;

	@Inject
	private ScrollBehaviorMouseWheelListener mouseWheelListener;

	@Override
	protected void startUp()
	{
		mouseManager.registerMouseWheelListener(mouseWheelListener);
		log.debug("Scroll Behavior plugin started");
	}

	@Override
	protected void shutDown()
	{
		mouseManager.unregisterMouseWheelListener(mouseWheelListener);
		mouseWheelListener.reset();
		log.debug("Scroll Behavior plugin stopped");
	}

	@Provides
	ScrollBehaviorConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ScrollBehaviorConfig.class);
	}
}

package com.scrollbehavior;

import java.awt.Canvas;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

public class ScrollBehaviorMouseWheelListenerTest
{
	private TestConfig config;
	private ScrollBehaviorMouseWheelListener listener;

	@Before
	public void setUp()
	{
		config = new TestConfig();
		listener = new ScrollBehaviorMouseWheelListener(config);
	}

	@Test
	public void normalSensitivityPreservesOriginalEvent()
	{
		MouseWheelEvent event = wheelEvent(1);

		assertSame(event, listener.mouseWheelMoved(event));
	}

	@Test
	public void slowerSensitivityAccumulatesPartialSteps()
	{
		config.sensitivity = 50;

		assertEquals(0, listener.mouseWheelMoved(wheelEvent(1)).getWheelRotation());
		assertEquals(1, listener.mouseWheelMoved(wheelEvent(1)).getWheelRotation());
	}

	@Test
	public void fasterSensitivityMultipliesSteps()
	{
		config.sensitivity = 300;

		assertEquals(-3, listener.mouseWheelMoved(wheelEvent(-1)).getWheelRotation());
	}

	@Test
	public void changingDirectionClearsPartialStep()
	{
		config.sensitivity = 50;

		assertEquals(0, listener.mouseWheelMoved(wheelEvent(1)).getWheelRotation());
		assertEquals(0, listener.mouseWheelMoved(wheelEvent(-1)).getWheelRotation());
		assertEquals(-1, listener.mouseWheelMoved(wheelEvent(-1)).getWheelRotation());
	}

	@Test
	public void reverseScrollingDirectionAtNormalSensitivity()
	{
		config.reverseScrollingDirection = true;

		assertEquals(-1, listener.mouseWheelMoved(wheelEvent(1)).getWheelRotation());
		assertEquals(1, listener.mouseWheelMoved(wheelEvent(-1)).getWheelRotation());
	}

	@Test
	public void reverseScrollingDirectionWithSlowerSensitivity()
	{
		config.sensitivity = 50;
		config.reverseScrollingDirection = true;

		assertEquals(0, listener.mouseWheelMoved(wheelEvent(1)).getWheelRotation());
		assertEquals(-1, listener.mouseWheelMoved(wheelEvent(1)).getWheelRotation());
	}

	@Test
	public void reverseScrollingDirectionWithFasterSensitivity()
	{
		config.sensitivity = 300;
		config.reverseScrollingDirection = true;

		assertEquals(3, listener.mouseWheelMoved(wheelEvent(-1)).getWheelRotation());
	}

	private static MouseWheelEvent wheelEvent(int rotation)
	{
		return new MouseWheelEvent(
			new Canvas(),
			MouseEvent.MOUSE_WHEEL,
			0,
			0,
			10,
			20,
			0,
			false,
			MouseWheelEvent.WHEEL_UNIT_SCROLL,
			1,
			rotation);
	}

	private static class TestConfig implements ScrollBehaviorConfig
	{
		private int sensitivity = 100;
		private boolean reverseScrollingDirection;

		@Override
		public int scrollSensitivity()
		{
			return sensitivity;
		}

		@Override
		public boolean reverseScrollingDirection()
		{
			return reverseScrollingDirection;
		}
	}
}

package com.scrollbehavior;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ScrollBehaviorPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ScrollBehaviorPlugin.class);
		RuneLite.main(args);
	}
}
